class Box {
    double width;
    double height;
    double depth;

    double volume() {
        return width * height * depth;
    }
}

Box b;          // declares reference
b = new Box();  // creates object

b.width = 10;
System.out.println(b.volume());

void setDim(double w, double h, double d) {
    width = w;
    height = h;
    depth = d;
}

b.setDim(10, 20, 15);

class Box {
    double width, height, depth;

    Box(double w, double h, double d) {
        width = w;
        height = h;
        depth = d;
    }
}

class Box {
    double width;
    Box(double width) {
        this.width = width;
    }
}

int add(int a, int b) { return a + b; }
double add(double a, double b) { return a + b; }
int add(int a, int b, int c) { return a + b + c; }

boolean sameBox(Box ob) {
    return width == ob.width &&
           height == ob.height &&
           depth == ob.depth;
}

Box bigger() {
    return new Box(width * 2,
                   height * 2,
                   depth * 2);
}

int fact(int n) {
    if (n == 0) return 1;
    return n * fact(n - 1);
}

class Counter {
    static int count = 0;
    Counter() { count++; }
}

System.out.println(Counter.count);
